package com.osrstrackernopaywall.playerdeath;

import com.google.gson.JsonObject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Player;
import com.osrstrackernopaywall.OsrsTrackerConfig;
import com.osrstrackernopaywall.api.ApiClient;
import com.osrstrackernopaywall.video.VideoRecorder;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.time.Instant;

@Slf4j
@Singleton
public class OtherPlayerDeathTracker
{
	private final Client client;
	private final ApiClient apiClient;
	private final OsrsTrackerConfig config;
	private final VideoRecorder videoRecorder;

	private static final int DEATH_POST_EVENT_MS = 5000;

	@Inject
	public OtherPlayerDeathTracker(Client client, ApiClient apiClient, OsrsTrackerConfig config, VideoRecorder videoRecorder)
	{
		this.client = client;
		this.apiClient = apiClient;
		this.config = config;
		this.videoRecorder = videoRecorder;
	}

	public void processActorDeath(Actor actor)
	{
		if (!config.trackOtherDeaths())
		{
			return;
		}

		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null || actor == localPlayer)
		{
			return;
		}

		if (actor instanceof Player)
		{
			log.debug("Player death detected");
			sendDeathEventToApi();
		}
	}

	private void sendDeathEventToApi()
	{
		videoRecorder.captureEventVideo(
			(screenshotBase64, videoBase64) -> {
				JsonObject payload = new JsonObject();
				payload.addProperty("timestamp", Instant.now().toString());

				String playerName = "unknown";
				if (client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null)
				{
					playerName = client.getLocalPlayer().getName();
				}
				payload.addProperty("playername", playerName);

				apiClient.sendEventToApi(
					"/api/webhooks/death",
					payload.toString(),
					"death",
					screenshotBase64,
					videoBase64
				);
			},
			null,
			DEATH_POST_EVENT_MS
		);
	}
}

